import json,subprocess,sys,datetime as dt
from pathlib import Path
R=Path('/data/qlyu/projects/peptide-four-task-benchmark-20261022');p=R/'methods/dta/node1-completed-backend-result-acceptance.json';summary=json.loads(p.read_text());out=[]
for x in summary:
 old=Path(x['result_path']);r=json.loads(old.read_text());c=json.loads(Path(r['contract_path']).read_text());actual=r['metric_comparisons'][0]['denominator'];defined=c['targets'][0]['denominator'];r['metric_comparisons'][0].update(denominator=defined,actual_test_denominator=actual);r['claims'][0]['text']+=' Actual held-out test n='+str(actual)+'; the frozen comparison-schema denominator='+str(defined)+' describes the complete input view and is not the scored test count.';r['recorded_at']=dt.datetime.now(dt.timezone.utc).isoformat();r['differences'].append({'category':'record schema clarification','description':'Original rejected administrative record preserved. Comparison denominator must equal the frozen contract total-view definition; actual test count remains separately explicit.','effect_on_comparison':'No fit, prediction, selection, metric, or contract was modified.','evidence_type':'source_fact','evidence_paths':[str(old),str(old.parent/'result-validation.json')]})
 dest=old.with_name('result-record-comparison-definition-v2.json');assert not dest.exists();dest.write_text(json.dumps(r,indent=2));v=subprocess.run([sys.executable,str(R/'resources/validate_reproduction.py'),'--contract',r['contract_path'],'--result',str(dest),'--check-files'],capture_output=True,text=True,timeout=120);validation=dest.with_name('result-validation-comparison-definition-v2.json');validation.write_text(v.stdout);q=json.loads(v.stdout);out.append({'job_id':x['job_id'],'valid_for_acceptance':q.get('valid_for_acceptance'),'errors':q.get('errors'),'result_path':str(dest),'validation_path':str(validation),'actual_test_denominator':actual,'frozen_comparison_schema_denominator':defined})
(R/'methods/dta/node1-completed-backend-result-acceptance-v2.json').write_text(json.dumps(out,indent=2));print(json.dumps(out))
